(function() {
    /*======== 版本更新日志 ========*/
    /*
     * 作者：sjshb57
     * GitHub：https://github.com/sjshb57/legado-57
     *
     * [v3.0.1] 第三十八次修改 - 前缀序号
     * - 步骤2 扩展为「数字.」前缀序号剥离，「1. 章节名 标题」不再误转为章节号
     * - 前缀序号与章节号以「.」区分：有点为序号，无点为章节号
     */

    // ========= 1. 功能文档 =========
    /*
     * 功能概述：
     * 本脚本是一个高级中文数字标题转换工具，专门用于处理各种格式的中文数字标题，
     * 将其转换为统一的阿拉伯数字格式，同时提供多种智能处理选项。
     * 
     */

    // ========= 2. 配置系统 =========
    /**
     * 可通过 Config 对象调整以下配置项：
     */
    const Config = {
        punctuationsToRemove: '.。,，、', // 需要统一删除的标点字符集
        convertZeroToPreface: false, // 是否将零值转换为"序"
        defaultSuffix: '章', // 覆盖使用此章节标识后缀
        preserveSuffixes: '卷次' // 白名单：这些标识符不被 defaultSuffix 覆盖，原样保留（空字符串则全部替换）
    };

    // ====== 3. 正则表达式系统 ======
    /*
     * Regex 对象封装所有预编译的正则表达式，避免重复编译，提升性能。
     * 标点相关的正则均根据 Config.punctuationsToRemove 动态构建。
     * leadingPunctuations / trailingPunctuations 供 assemble 清理衔接处与末尾，
     * allPunctuations 仅用于非章节标题的全文删除。
     * chapter / digitalChapter 的标识符字符类由 baseSuffixes + preserveSuffixes
     * 动态合并，每个字符单独转义，防止特殊字符破坏正则字符类。
     * digitalTimeUnit / leadingTimeUnit 共用 timeUnits 字符类，已剔除被标识符占用的字符。
     */
    var punctEscape = /[-\]\\\^[\/.*+?()|{}$]/g;
    var escaped = Config.punctuationsToRemove.replace(punctEscape, '\\$&');
    var baseSuffixes = '章节回集卷部篇话讲段';
    var extraSuffixes = '';
    for (var si = 0; si < Config.preserveSuffixes.length; si++) {
        var sch = Config.preserveSuffixes.charAt(si);
        var schEscaped = sch.replace(punctEscape, '\\$&');
        if (baseSuffixes.indexOf(sch) < 0 && extraSuffixes.indexOf(sch) < 0) extraSuffixes += schEscaped;
    }
    var allSuffixes = baseSuffixes + extraSuffixes;
    var timeUnitsBase = '季年月日周天期次';
    var timeUnits = '';
    for (var ti = 0; ti < timeUnitsBase.length; ti++) {
        var tch = timeUnitsBase.charAt(ti);
        if (allSuffixes.indexOf(tch) < 0) timeUnits += tch;
    }
    var Regex = {
        patterns: {
            chapter: new RegExp('^第(\\d+|[零〇一二三四五六七八九十百千两万壹贰叁肆伍陆柒捌玖拾佰仟萬貳參陸]+)([' + allSuffixes + ']?)(.*)'),
            digitalChapter: new RegExp('^(\\d+)([' + allSuffixes + ']?)(.*)'),
            digitalTimeUnit: timeUnits ? new RegExp('^\\d+[' + timeUnits + ']') : null,
            leadingTimeUnit: timeUnits ? new RegExp('^[' + timeUnits + ']') : null,
            chinesePunctuation: /^[：、；？！。…]/,
            leadingPunctuations: new RegExp('^[\\s' + escaped + ']+'),
            trailingPunctuations: new RegExp('[\\s' + escaped + ']+$'),
            allPunctuations: new RegExp('[' + escaped + ']', 'g')
        }
    };

    // 半角→全角标点映射表（仅用于章节号与标题间的分隔字符转换）
    var halfToFull = {
        ':': '：',
        '!': '！',
        '?': '？',
        ',': '，',
        ';': '；'
    };

    // ======= 4. 数字转换系统 =======
    /*
     * NumberConverter 负责将中文数字字符串转换为阿拉伯数字。
     *
     * map 映射表覆盖：
     *   基础数字：零〇一二两三四五六七八九（含同义词）
     *   单位数字：十百千万（进位单位）
     *   财务大写：壹贰叁肆伍陆柒捌玖拾佰仟萬
     *   繁体数字：貳參陸
     *
     * convert 算法（逐字扫描，O(n) 时间，O(1) 空间）：
     *   维护 total（累计值）和 temp（待与进位单位相乘的临时值）两个变量。
     *   遇到进位单位时 temp 为 0 则视为隐含的 1（如『十二』→ 12），
     *   temp × 单位累加到 total 后归零；遇到普通数字则 temp += 数值。
     */
    var NumberConverter = {
        map: {
            // 基础数字
            '零': 0,
            '〇': 0,
            '一': 1,
            '二': 2,
            '两': 2,
            '三': 3,
            '四': 4,
            '五': 5,
            '六': 6,
            '七': 7,
            '八': 8,
            '九': 9,
            // 进位单位
            '十': 10,
            '百': 100,
            '千': 1000,
            '万': 10000,
            // 财务大写
            '壹': 1,
            '贰': 2,
            '叁': 3,
            '肆': 4,
            '伍': 5,
            '陆': 6,
            '柒': 7,
            '捌': 8,
            '玖': 9,
            '拾': 10,
            '佰': 100,
            '仟': 1000,
            '萬': 10000,
            // 繁体
            '貳': 2,
            '參': 3,
            '陸': 6
        },

        convert: function(chineseNum) {
            var total = 0;
            var temp = 0;

            for (var i = 0; i < chineseNum.length; i++) {
                var val = this.map[chineseNum.charAt(i)]; // Rhino 兼容：用 charAt(i) 替代 [i]
                if (val === 10 || val === 100 || val === 1000 || val === 10000) {
                    temp = (temp === 0 ? 1 : temp) * val;
                    total += temp;
                    temp = 0;
                } else if (val !== undefined) {
                    temp += val;
                }
            }

            return total + temp;
        }
    };

    // ======== 5. 工具函数 ========
    /*
     * assemble()：章节号与标题内容的统一组装函数。
     * 步骤4（数字标题分支）与步骤8（第X章分支）共用。
     * 先清理 titlePart 的衔接处与末尾标点，标题内部的标点原样保留。
     *
     * 分隔策略（按优先级）：
     *   1. halfToFull 中的半角标点 → 转换为对应全角标点，直接拼接
     *   2. 中文标点（：、；？！。…）→ 原样保留，直接拼接，不补空格
     *   3. 原有分隔空格、直接是汉字或英文数字 → 补半角空格
     *   4. 其他符号 → 原样保留，直接拼接
     */
    function assemble(prefix, suffix, titlePart) {
        // 用户要求章节号统一为「第 X 章」：在「第」与数字、数字与后缀之间保留空格。
        // prefix 为空时（零值分支「序章」）不处理，保持原行为。
        var headText = /^第.+$/.test(prefix) ? ('第 ' + prefix.slice(1) + ' ' + suffix) : (prefix + suffix);
        var hadSpace = /^\s/.test(titlePart);
        var cleanPart = titlePart
            .replace(Regex.patterns.leadingPunctuations, '')
            .replace(Regex.patterns.trailingPunctuations, '');
        if (!cleanPart) return headText;
        var firstChar = cleanPart.charAt(0);
        if (halfToFull[firstChar]) {
            // 半角标点 → 转全角后直接拼接，内容从第2字符起
            return headText + halfToFull[firstChar] + cleanPart.slice(1).replace(/^\s+/, '');
        } else if (Regex.patterns.chinesePunctuation.test(firstChar)) {
            // 中文标点 → 原样保留，直接拼接，不补空格
            return headText + cleanPart;
        } else if (hadSpace || /[\u4e00-\u9fff\w]/.test(firstChar)) {
            // 原有分隔空格、汉字或英文数字 → 补半角空格
            return headText + ' ' + cleanPart;
        } else {
            // 其他符号（括号、引号等）→ 原样保留，直接拼接
            return headText + cleanPart;
        }
    }

    /*
     * resolveSuffix()：后缀解析。白名单内的标识符原样保留，其余统一使用 defaultSuffix。
     * 空标识符必须先判空，否则 indexOf('') 恒返回 0 会被误判为白名单命中。
     */
    function resolveSuffix(originalSuffix) {
        return (originalSuffix && Config.preserveSuffixes.indexOf(originalSuffix) >= 0) ?
            originalSuffix : Config.defaultSuffix;
    }

    // ======== 6. 主处理函数 ========

    function processTitle(title) {

        // --- 步骤1：括号内容处理 ---
        // 含黑名单字符的括号内容整体删除，其余转为「 (内容) 」（半角括号两侧补空格）。
        // 拆为闭合/未闭合两步，避免 g 标志 + $ 锚定的回溯问题。
        var bracketBlacklist = /[票更快祝新迎章订架求免]/;
        title = title.replace(/[（(]([^）)]*)[）)]/g, function(_, inner) {
            return bracketBlacklist.test(inner) ? '' : ' (' + inner + ') ';
        });
        title = title.replace(/[（(]([^）)]*)$/, function(_, inner) {
            return bracketBlacklist.test(inner) ? '' : ' (' + inner + ')';
        });
        title = title.replace(/ {2,}/g, ' ').replace(/^ +| +$/g, '');

        // --- 步骤2：前缀序号剥离 ---
        // 「数字.」开头视为前缀序号（列表序号 / 日期 / 编号），如「1. 章节名」「8.29 请假」。
        // 与章节号区分：章节号数字后直接跟内容或标识符（如「60你好」「58章」），不带「.」。
        // 须在步骤3之前判断，否则「.」会先被 cleaned 删掉，前缀特征就没了。
        // 剥离后交回后续流程，「1.1 第三章 标题」仍可正常转换。
        if (/^\d+\./.test(title)) {
            var stripped = title.replace(/^[\d.]+/, '').replace(/^\s+|\s+$/g, '');
            // 剥离后无内容（纯数字如「8.29」）则原样返回，不当作章节号处理
            if (!stripped) return title;
            title = stripped;
        }

        // --- 步骤3：统一标点预处理 ---
        // 章节标题仅清理衔接处与末尾（见 assemble），标题内标点保留；
        // 非章节标题走全文删除后的 cleaned。
        var cleaned = title.replace(Regex.patterns.allPunctuations, '');

        // --- 步骤4：数字标题处理 ---
        // 处理「29章 请假」「456内容」「58、标题」等数字开头格式，
        // 标识符与内容一次匹配到位，避免「章」字被误吞入内容。
        if (Regex.patterns.digitalTimeUnit && Regex.patterns.digitalTimeUnit.test(title)) {
            return cleaned;
        }
        var digitalMatch = title.match(Regex.patterns.digitalChapter);
        if (digitalMatch) {
            return assemble('第' + digitalMatch[1], resolveSuffix(digitalMatch[2]), digitalMatch[3]);
        }

        // --- 步骤5：非「第」开头标题处理 ---
        // 不以「第」开头则无章节号可转换，直接返回。
        if (title.charAt(0) !== '第') return cleaned;

        // --- 步骤6：正则匹配「第X章」标题各部分 ---
        // 提取 chineseNum（数字）、originalSuffix（标识符）、titlePart（内容）。
        // 匹配失败（如「第abc章」）则原样返回。
        var match = title.match(Regex.patterns.chapter);
        if (!match) return cleaned;

        var chineseNum = match[1];
        var originalSuffix = match[2];
        var titlePart = match[3] || '';

        // 无标识符时，若 titlePart 以时间词开头则原样返回，避免误匹配
        if (!originalSuffix && Regex.patterns.leadingTimeUnit &&
            Regex.patterns.leadingTimeUnit.test(titlePart.replace(/^\s+/, ''))) {
            return cleaned;
        }

        var suffix = resolveSuffix(originalSuffix);

        // --- 步骤7：数字转换 ---
        // chineseNum 为阿拉伯数字时直接使用，否则调用 NumberConverter.convert 转换。
        var number = /^\d+$/.test(chineseNum) ? chineseNum : NumberConverter.convert(chineseNum);

        // --- 步骤8：零值处理与结果组装 ---
        // Number() 显式转换，避免字符串与 0 严格比较失败。
        // 零值标题不带「第」前缀，直接使用「序」+ suffix。
        if (Number(number) === 0 && Config.convertZeroToPreface) {
            return assemble('', '序' + suffix, titlePart);
        }
        return assemble('第' + number, suffix, titlePart);
    }

    // ========== 执行入口 ==========
    // result 是阅读软件传入的原始标题文本，processTitle 处理后返回转换结果。
    return processTitle(result);
})();

